1	// Geometry helpers shared by all subsystems. Scene units are metres; hardpoints are mm in the vehicle frame (x fwd, y left, z up).
2	import * as THREE from "three";
3	
4	export const V = (x, y, z) => new THREE.Vector3(x, y, z);
5	export const mm = v => V(v[0] / 1000, v[1] / 1000, v[2] / 1000);
6	export const Y = V(0, 1, 0);
7	const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 16), sphGeo = new THREE.SphereGeometry(1, 16, 12);
8	
9	export const mat = (c = 0xffffff, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.5, metalness: 0.15, ...o });
10	export const glass = (c = 0x8fa3b3, opacity = 0.12) => new THREE.MeshStandardMaterial({ color: c, transparent: true, opacity, depthWrite: false, side: THREE.DoubleSide });
11	export const line = (c = 0x8fa3b3, opacity = 0.6) => new THREE.LineBasicMaterial({ color: c, transparent: true, opacity });
12	
13	// Unit cylinder stretched between two points by place(); r = radius (m).
14	export function rod(m, r) { const o = new THREE.Mesh(cylGeo, m); o.userData.r = r; return o; }
15	export function place(o, a, b) {
