1	// Declarative side-panel cards. A subsystem describes its cards; this builds the DOM (textContent only) and returns handles.
2	// Card: { label, badge?: { id, text }, only?: "model" | "photo", items: [widget] }. Widgets (one key each, plus optional `only`):
3	//   readouts: [{ id, label, unit, value }]          → ui.set(id, text)
4	//   trace: { id, series: [{ token, min, max }], span, top, bottom, aria }   → ui.trace(id).push(t, [v…]) / .draw(t)
5	//   buttons: [{ id, label, toggle?: [onLabel, offLabel], pressed?, onClick(pressed) }]   → ui.toggle(id).set(bool)
6	//   slider: { id, label, min, max, step, value, onInput(v) }   → ui.slider(id).set(v)
7	//   meter: { id }  → ui.meter(id).set(0..1, hot)        cells: { id, labels }  → ui.cells(id).set(i, text, on)
8	//   legend: [[token, name]]   key: [[token, text]]   svg: { id, viewBox, aria }  → ui.el(id)   text: "…"   list: ["…"]
9	// Text arrives already translated (subsystems use ctx.t); readout values are written with the local decimal mark.
10	import { num } from "./i18n.js";
11	
12	const SVG = "http://www.w3.org/2000/svg";
13	
14	function h(tag, attrs = {}, ...kids) {
15	  const el = tag.startsWith("svg:") ? document.createElementNS(SVG, tag.slice(4)) : document.createElement(tag);
16	  for (const [k, v] of Object.entries(attrs)) if (v != null && v !== false) el.setAttribute(k, v === true ? "" : v);
17	  for (const k of kids.flat()) if (k != null) el.append(k);
18	  return el;
19	}
20	
21	export function createPanel(container, compId) {
22	  const els = new Map(), api = {};
23	  const key = id => `${compId}-${id}`;
24	
25	  const widgets = {
26	    readouts: items => h("div", { class: "readouts" }, items.map(r => {
27	      const o = h("output", { id: key(r.id) }, r.value ?? "–"); els.set(r.id, o);
28	      return h("div", {}, h("small", {}, r.label), o, h("small", {}, r.unit ?? ""));
29	    })),
30	    trace: t => {
31	      const svg = h("svg:svg", { viewBox: "0 0 280 110", role: "img", "aria-label": t.aria ?? "" });
32	      const grid = [[55, null], [5, "2 3"], [105, "2 3"]].map(([y, dash]) => h("svg:line", { x1: 0, y1: y, x2: 280, y2: y, stroke: "var(--rule)", "stroke-dasharray": dash }));
33	      const lines = t.series.map(s => h("svg:polyline", { fill: "none", stroke: `var(${s.token})`, "stroke-width": 1.6 }));
34	      svg.append(...grid, ...lines, h("svg:text", { x: 278, y: 15, "text-anchor": "end" }, t.top ?? ""), h("svg:text", { x: 278, y: 101, "text-anchor": "end" }, t.bottom ?? ""));
35	      const buf = [], span = t.span ?? 6;
36	      els.set(t.id, {
37	        push(time, values) { buf.push({ time, values }); },
38	        draw(now) {
39	          while (buf.length && buf[0].time < now - span) buf.shift();
40	          const X = tt => ((tt - (now - span)) / span * 280).toFixed(1);
41	          t.series.forEach((s, i) => lines[i].setAttribute("points", buf.map(p => {
42	            const v = Math.max(s.min, Math.min(s.max, p.values[i]));
43	            return `${X(p.time)},${(105 - (v - s.min) / (s.max - s.min) * 100).toFixed(1)}`;
44	          }).join(" ")));
45	        },
46	      });
47	      return h("div", { class: "trace" }, svg);
48	    },
49	    buttons: items => h("div", { class: "row" }, items.map(b => {
50	      // toggle: [onLabel, offLabel] flips itself; pressed without toggle = radio-style button whose state the caller sets.
51	      const el = h("button", { type: "button", "aria-pressed": b.toggle || b.pressed != null ? String(!!b.pressed) : null }, b.toggle ? b.toggle[b.pressed ? 0 : 1] : b.label);
52	      const handle = { el, pressed: !!b.pressed, set(p) { handle.pressed = p; el.setAttribute("aria-pressed", String(p)); if (b.toggle) el.textContent = b.toggle[p ? 0 : 1]; } };
53	      el.addEventListener("click", () => { if (b.toggle) handle.set(!handle.pressed); b.onClick?.(handle.pressed); });
54	      els.set(b.id, handle);
55	      return el;
56	    })),
57	    slider: s => {
58	      const input = h("input", { id: key(s.id), type: "range", min: s.min, max: s.max, step: s.step ?? 1, value: s.value });
59	      input.addEventListener("input", () => s.onInput?.(+input.value));
60	      els.set(s.id, { el: input, set(v) { input.value = v; } });
61	      return h("div", { class: "slider" }, h("label", { class: "label", for: key(s.id) }, s.label), input);
62	    },
63	    meter: m => { const bar = h("i"), el = h("div", { class: "meter" }, bar); els.set(m.id, { set(f, hot) { bar.style.width = `${(Math.max(0, Math.min(1, f)) * 100).toFixed(0)}%`; el.classList.toggle("hot", !!hot); } }); return el; },
64	    cells: c => {
65	      const cells = c.labels.map(l => h("div", { class: "cyl" }, h("b", {}, l), h("span", {}, "–")));
