13	  const fill = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.06, depthWrite: false, side: THREE.DoubleSide });
14	  const edge = new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 });
