24	        const e = new THREE.Euler(...(t.rot ?? [0, 0, 0]).map(a => a * D));
25	        geo.applyMatrix4(new THREE.Matrix4().makeRotationFromEuler(e)).translate(t.pos[0] / 1000, s * t.pos[1] / 1000, t.pos[2] / 1000);
26	      } else if (part.cyl) {
27	        const c = part.cyl;
28	        geo = new THREE.CylinderGeometry(c.r[0] / 1000, c.r[1] / 1000, c.h / 1000, 20);
29	        if (c.axis === "x") geo.rotateZ(Math.PI / 2); else if (c.axis === "z") geo.rotateX(Math.PI / 2);
30	        geo.translate(c.pos[0] / 1000, s * c.pos[1] / 1000, c.pos[2] / 1000);
31	      }
32	      if (geo) edgesOf(geo, group, fill, edge, 25);
33	    }
34	  }
35	  return { group, fill, edge };
