11	export const line = (c = 0x8fa3b3, opacity = 0.6) => new THREE.LineBasicMaterial({ color: c, transparent: true, opacity });
12	
13	// Unit cylinder stretched between two points by place(); r = radius (m).
14	export function rod(m, r) { const o = new THREE.Mesh(cylGeo, m); o.userData.r = r; return o; }
15	export function place(o, a, b) {
16	  const d = new THREE.Vector3().subVectors(b, a), len = d.length();
17	  o.position.copy(a).addScaledVector(d, 0.5);
18	  if (len > 1e-9) o.quaternion.setFromUnitVectors(Y, d.multiplyScalar(1 / len));
19	  o.scale.set(o.userData.r, Math.max(len, 1e-6), o.userData.r);
20	  return o;
21	}
22	export function ball(m, r, p) { const o = new THREE.Mesh(sphGeo, m); o.scale.setScalar(r); if (p) o.position.copy(p); return o; }
23	
24	// Coil spring between a and b.
25	export function helix(a, b, turns = 7, r = 0.046, wire = 0.007) {
26	  const d = new THREE.Vector3().subVectors(b, a), len = d.length(), n = d.clone().normalize();
27	  const t1 = V(1, 0, 0).cross(n).normalize(), t2 = n.clone().cross(t1), pts = [];
28	  for (let i = 0; i <= 200; i++) {
29	    const u = i / 200, th = u * Math.PI * 2 * turns;
30	    pts.push(a.clone().addScaledVector(n, u * len).addScaledVector(t1, Math.cos(th) * r).addScaledVector(t2, Math.sin(th) * r));
31	  }
32	  return new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 200, wire, 6, false);
33	}
34	
35	// Tyre (torus) with its axis along y. R = ring radius, r = section radius (m).
36	export function tyre(m, R = 0.235, r = 0.057) {
37	  const g = new THREE.Group();
38	  const t = new THREE.Mesh(new THREE.TorusGeometry(R, r, 14, 56), m); t.rotation.x = Math.PI / 2; g.add(t);
39	  return g;
40	}
41	
42	// Tyre on a wire wheel, axis along y. spokeMat is a LineBasicMaterial; spokeMat.userData.solid is the rim material.
43	export function wireWheel(tyreMat, spokeMat, R = 0.295, r = 0.085, spokeR = 0.215, spokes = 32) {
44	  const g = tyre(tyreMat, R, r);
45	  if (spokeMat) {
46	    const pts = [];
47	    for (let i = 0; i < spokes; i++) {
48	      const a = i / spokes * Math.PI * 2, side = i % 2 ? 0.035 : -0.035;
49	      pts.push(0, side, 0, spokeR * Math.cos(a), 0, spokeR * Math.sin(a));
50	    }
51	    const sg = new THREE.BufferGeometry(); sg.setAttribute("position", new THREE.Float32BufferAttribute(pts, 3));
52	    g.add(new THREE.LineSegments(sg, spokeMat));
53	    const rim = new THREE.Mesh(new THREE.TorusGeometry(spokeR, 0.008, 6, 48), spokeMat.userData.solid); rim.rotation.x = Math.PI / 2; g.add(rim);
54	  }
55	  return g;
56	}
57	
58	// Wooden artillery-style wheel (spokes as rods), axis along y.
59	export function spokedWheel(tyreMat, spokeMat, R = 0.42, spokes = 12) {
60	  const g = tyre(tyreMat, R, 0.022);
61	  for (let i = 0; i < spokes; i++) { const a = i / spokes * Math.PI * 2; g.add(place(rod(spokeMat, 0.012), V(0, 0, 0), V(R * Math.cos(a), 0, R * Math.sin(a)))); }
62	  g.add(place(rod(spokeMat, 0.05), V(0, -0.06, 0), V(0, 0.06, 0)));
63	  return g;
64	}
65	
66	export function edgesOf(geo, group, fillMat, lineMat, thresh = 22) {
67	  group.add(new THREE.Mesh(geo, fillMat), new THREE.LineSegments(new THREE.EdgesGeometry(geo, thresh), lineMat));
68	}
69	
70	// Points along an arc in a 2-D profile (mm, degrees).
71	export const arc = (cx, cz, r, a0, a1, n = 14) => Array.from({ length: n + 1 }, (_, i) => {
72	  const a = (a0 + (a1 - a0) * i / n) * Math.PI / 180; return [cx + r * Math.cos(a), cz + r * Math.sin(a)];
73	});
74	
75	// Side-profile polygon (x, z in mm) extruded across y from y0 to y1 (mm). Entries may be { arc: [cx, cz, r, a0, a1, n] }.
76	export function profileExtrude(pts, y0, y1) {
77	  const flat = pts.flatMap(p => (p.arc ? arc(...p.arc) : [p]));
78	  const s = new THREE.Shape(); s.moveTo(flat[0][0], flat[0][1]); for (const p of flat.slice(1)) s.lineTo(p[0], p[1]);
79	  const g = new THREE.ExtrudeGeometry(s, { depth: y1 - y0, bevelEnabled: false });
80	  g.rotateX(Math.PI / 2); g.translate(0, y1, 0); g.scale(0.001, 0.001, 0.001);
81	  return g;
82	}
83	
84	export function pipe(points, r, m) {
85	  return new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points, false, "catmullrom", 0.1), 48, r, 10, false), m);
86	}
87	
88	// Spur gear, axis along x.
89	export function gear(R, teeth, w, m) {
90	  const g = new THREE.Group(), body = new THREE.Mesh(new THREE.CylinderGeometry(R - 0.006, R - 0.006, w, 48), m); body.rotation.z = Math.PI / 2; g.add(body);
91	  for (let i = 0; i < teeth; i++) {
92	    const a = i / teeth * Math.PI * 2, t = new THREE.Mesh(new THREE.BoxGeometry(w, 0.012, 0.008), m);
93	    t.position.set(0, R * Math.cos(a), R * Math.sin(a)); t.rotation.x = a; g.add(t);
94	  }
95	  return g;
96	}
97	
98	// Polyline parametrised by arc length, for particles: at(pl, s ∈ [0,1], out).
99	export function polyline(points) {
100	  const segs = []; let tot = 0;
101	  for (let i = 1; i < points.length; i++) { const l = points[i].distanceTo(points[i - 1]); segs.push(l); tot += l; }
102	  return { points, segs, tot };
103	}
104	export function at(pl, s, out) {
105	  let d = s * pl.tot;
106	  for (let i = 0; i < pl.segs.length; i++) {
107	    if (d <= pl.segs[i] || i === pl.segs.length - 1) return out.copy(pl.points[i]).lerp(pl.points[i + 1], Math.min(1, d / pl.segs[i]));
108	    d -= pl.segs[i];
109	  }
110	  return out.copy(pl.points[pl.points.length - 1]);
111	}
112	
113	// Point cloud whose positions/colours are rewritten each frame.
114	export function particles(n, size = 0.026) {
115	  const pos = new Float32Array(n * 3), col = new Float32Array(n * 3), geo = new THREE.BufferGeometry();
116	  geo.setAttribute("position", new THREE.BufferAttribute(pos, 3)); geo.setAttribute("color", new THREE.BufferAttribute(col, 3));
117	  const pts = new THREE.Points(geo, new THREE.PointsMaterial({ size, vertexColors: true, transparent: true, opacity: 0.95, depthTest: false }));
118	  pts.renderOrder = 6;
119	  return { pts, pos, col, set(i, p, c) { pos.set([p.x, p.y, p.z], i * 3); col.set([c.r, c.g, c.b], i * 3); },
120	    flush() { geo.attributes.position.needsUpdate = true; geo.attributes.color.needsUpdate = true; } };
121	}
