1	// Renderer, cameras, lights, theme tokens and the frame loop for one stop. Owns nothing car-specific.
2	import * as THREE from "three";
3	import { OrbitControls } from "three/addons/controls/OrbitControls.js";
4	import { mm } from "./helpers.js";
5	
6	// el: the .stage element (keeps the photo's aspect). car: the car config (photo, orbit, sun).
7	export function createStage(el, car) {
8	  const photo = car.photo, aspect = photo ? photo.w / photo.h : 1200 / 803;
9	  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
10	  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
11	  renderer.outputColorSpace = THREE.SRGBColorSpace;
12	  const img = el.querySelector("img");   // the transparent canvas sits on top of the museum photo
13	  if (img) img.after(renderer.domElement); else el.prepend(renderer.domElement);
14	  // iOS drops WebGL contexts of background tabs; preventDefault lets the browser restore it.
15	  renderer.domElement.addEventListener("webglcontextlost", e => e.preventDefault());
16	
17	  const scene = new THREE.Scene();
18	  const cam = new THREE.PerspectiveCamera(32, aspect, 0.05, 60);
19	  cam.up.set(0, 0, 1);
20	  const controls = new OrbitControls(cam, renderer.domElement);
21	  controls.enableDamping = true;
22	  controls.minDistance = car.orbit?.min ?? 0.8; controls.maxDistance = car.orbit?.max ?? 16;
23	
24	  // Camera fitted to the museum photo (tools/fit-photo-camera.mjs): position in mm, yaw/pitch/roll in rad, focal length in px.
25	  let photoCam = null;
26	  if (photo) {
27	    const { c, yaw, pitch, roll, f } = photo.cam;
28	    photoCam = new THREE.PerspectiveCamera(2 * Math.atan(photo.h / 2 / f) * 180 / Math.PI, aspect, 0.05, 60);
29	    const fw = new THREE.Vector3(Math.cos(pitch) * Math.cos(yaw), Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch));
30	    const r = new THREE.Vector3().crossVectors(fw, new THREE.Vector3(0, 0, 1)).normalize();
31	    const u = new THREE.Vector3().crossVectors(r, fw);
32	    photoCam.position.copy(mm(c));
33	    photoCam.up.copy(u.clone().multiplyScalar(Math.cos(roll)).addScaledVector(r, -Math.sin(roll)));
34	    photoCam.lookAt(photoCam.position.clone().add(fw));
35	  }
36	
37	  // Physically based light units since r155: intensities are the PoC's r128 values × π.
38	  scene.add(new THREE.HemisphereLight(0xffffff, 0x445566, 0.95 * Math.PI));
39	  const sun = new THREE.DirectionalLight(0xffffff, 0.65 * Math.PI); sun.position.set(...(car.sun ?? [3, 4, 6])); scene.add(sun);
40	
41	  // Theme: colours live in CSS custom properties; bind(color, token) re-applies them on theme change.
42	  const root = document.documentElement;
43	  const css = n => getComputedStyle(root).getPropertyValue(n).trim();
44	  const cache = new Map(), bindings = [], onTheme = [];
45	  const color = token => { if (!cache.has(token)) cache.set(token, new THREE.Color(css(token))); return cache.get(token); };
46	  const isDark = () => root.dataset.theme === "dark" || (root.dataset.theme !== "light" && matchMedia("(prefers-color-scheme: dark)").matches);
47	  let onPhoto = false;
48	  function applyColors() {
49	    cache.clear();
50	    for (const [c, token] of bindings) c.copy(color(token));
51	    scene.background = onPhoto ? null : color("--stage").clone();
52	    for (const fn of onTheme) fn({ onPhoto, dark: isDark() });
53	  }
54	  matchMedia("(prefers-color-scheme: dark)").addEventListener("change", applyColors);
55	  new MutationObserver(applyColors).observe(root, { attributes: true, attributeFilter: ["data-theme"] });
56	
57	  function resize() {
58	    const w = el.clientWidth, h = el.clientHeight;
59	    if (!w || !h) return;
60	    renderer.setSize(w, h, false); cam.aspect = w / h; cam.updateProjectionMatrix();
61	  }
62	  new ResizeObserver(resize).observe(el);
63	
64	  const stats = { frames: 0 };
65	  return {
66	    THREE, renderer, scene, cam, photoCam, controls, css, color, isDark, stats,
67	    bind(c, token) { bindings.push([c, token]); c.copy(color(token)); return c; },
68	    tokenMat(token, o) { const m = new THREE.MeshStandardMaterial({ roughness: 0.5, metalness: 0.15, ...o }); this.bind(m.color, token); return m; },
69	    onTheme(fn) { onTheme.push(fn); },
70	    applyColors,
71	    setPhotoView(on) { onPhoto = on && !!photoCam; controls.enabled = !onPhoto; applyColors(); },
72	    setOrbit(v) { cam.position.set(...v.pos); controls.target.set(...v.target); controls.update(); },
73	    // onFrame(dt) runs before each render; dt in s, clamped so a paused tab or slow frame never jumps the simulation.
74	    start(onFrame) {
75	      resize();
76	      let last = performance.now();
77	      renderer.setAnimationLoop(now => {
78	        const dt = Math.min((now - last) / 1000, 0.05); last = now;
79	        onFrame(dt);
80	        if (!onPhoto) controls.update();
81	        renderer.render(scene, onPhoto ? photoCam : cam);
82	        stats.frames++;
83	      });
84	    },
85	  };
86	}
87

