1	// Page shell for every stop: stop.html?s=<slug>[&r=teaser]. Builds the page from stops/tour.js + stops/<slug>/car.js, loads
2	// each component's subsystem, and owns the Component/View switches, photo view, car outline, ghost body and frame loop.
3	// With r=teaser (links from teaser.html) prev/next, the stop count and the back link stay within the teaser.
4	import tour, { teaser } from "../../stops/tour.js";
5	import { createPanel } from "./panel.js";
6	import { registerOffline } from "./offline.js";
7	import { t, loadCar, localizePage, missing } from "./i18n.js";
8	
9	const params = new URLSearchParams(location.search);
10	const slug = params.get("s");
11	const teaserStops = tour.filter(s => teaser.includes(s.slug));
12	const inTeaser = params.get("r") === "teaser" && teaserStops.some(s => s.slug === slug);
13	const route = inTeaser ? teaserStops : tour;
14	const idx = route.findIndex(s => s.slug === slug);   // validated before any dynamic import
15	const app = document.getElementById("app");
16	
17	function h(tag, attrs = {}, ...kids) {
18	  const el = document.createElement(tag);
19	  for (const [k, v] of Object.entries(attrs)) if (v != null && v !== false) el.setAttribute(k, v === true ? "" : v);
20	  for (const k of kids.flat()) if (k != null) el.append(k);
21	  return el;
22	}
23	const link = (href, text) => h("a", { href, target: href.startsWith("http") ? "_blank" : null, rel: href.startsWith("http") ? "noopener" : null }, text);
24	const seg = (key, label, items, cur) => h("div", { class: "seg-group", "data-key": key }, h("span", { class: "seg-label" }, label),
25	  h("span", { class: "seg", role: "group", "aria-label": label }, items.map(([v, text]) => h("button", { type: "button", "data-v": v, "aria-pressed": String(v === cur) }, text))));
26	
27	localizePage();
28	registerOffline();
29	if (inTeaser) Object.assign(document.getElementById("back"), { href: "teaser.html", textContent: t("← Highlights") });
30	if (idx < 0) {
31	  document.title = t("Stop not found · Museum tour");
32	  app.replaceChildren(h("h1", {}, t("Stop not found")), h("p", {}, t("This QR code or link does not match a stop on the tour."), " ", link("./", t("Open the tour route"))));
33	} else {
34	  main().catch(err => {
35	    console.error(err);
36	    const stage = document.getElementById("stage");
37	    (stage ?? app).append(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
38	  });
39	}
40	
41	async function main() {
42	  const stop = route[idx];
43	  const car = await loadCar(stop.slug);
44	  const base = `stops/${stop.slug}/`;
45	  document.title = t("{0} · Museum tour", car.name);
46	  const state = { comp: car.components[0].id, view: "model", outline: false };
47	  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
48	
49	  // ---------- page ----------
50	  const prev = route[idx - 1], next = route[idx + 1], here = s => `stop.html?s=${s.slug}${inTeaser ? "&r=teaser" : ""}`;
51	  const nameOf = async s => (s ? (await loadCar(s.slug)).name : null);
52	  const [prevName, nextName] = await Promise.all([nameOf(prev), nameOf(next)]);
53	  const photo = car.photo;
54	  const img = photo ? h("img", { src: base + photo.src, alt: photo.alt, width: photo.w, height: photo.h, hidden: true }) : null;
55	  const credit = photo ? h("div", { class: "credit", hidden: true }, t("Photo:"), " ", link(photo.credit.url, photo.credit.author), `, ${photo.credit.license}`) : null;
56	  const hint = h("div", { class: "hint" }, t("drag to orbit · pinch to zoom"));
57	  const stageEl = h("div", { class: "stage", id: "stage", style: photo ? `--aspect:${photo.w}/${photo.h};--ar:${(photo.w / photo.h).toFixed(4)}` : null }, img, hint, credit);
58	  const side = h("div", { class: "side" });
59	  const outlineBtn = h("button", { type: "button", class: "outline", "aria-pressed": "false", "data-only": "photo" }, t("Car outline"));
60	  const toolbar = h("div", { class: "toolbar" },
61	    car.components.length > 1 ? seg("comp", t("Component"), car.components.map(c => [c.id, c.label]), state.comp) : null,
62	    photo ? seg("view", t("View"), [["model", t("3D model")], ["photo", t("Museum photo")]], state.view) : null,
