78	  const stage = createStage(stageEl, car);
79	  const carRoot = new stage.THREE.Group(); stage.scene.add(carRoot);
80	  const ghost = buildGhost(car.body?.ghost); carRoot.add(ghost.group);
81	  stage.onTheme(({ onPhoto }) => { const c = onPhoto ? new stage.THREE.Color(0xffffff) : stage.color("--fg"); ghost.fill.color.copy(c); ghost.edge.color.copy(c); });
82	
83	  const instances = new Map();
84	  for (const comp of car.components) {
85	    if (!/^[a-z0-9-]+$/.test(comp.subsystem)) throw new Error(`bad subsystem id ${comp.subsystem}`);
86	    const mod = await import(`../../subsystems/${comp.subsystem}.js`);
87	    const panel = createPanel(side, comp.id);
88	    const inst = mod.create({ stage, carRoot, frame: car.frame, ride: car.ride, panel, reducedMotion, t }, comp.params);
89	    panel([{ label: t("What to say at the car"), items: [{ list: comp.talk }] }]);
90	    instances.set(comp.id, inst);
91	  }
92	  if (car.note) side.append(h("p", { class: "note" }, car.note));
93	
94	  function layout(resetOrbit = true) {
95	    const onPhoto = state.view === "photo", comp = car.components.find(c => c.id === state.comp);
96	    document.querySelectorAll("[data-comp]").forEach(el => (el.hidden = el.dataset.comp !== state.comp));
97	    document.querySelectorAll("[data-only]").forEach(el => { if (!el.closest("[data-comp]")?.hidden) el.hidden = (el.dataset.only === "photo") !== onPhoto; });
98	    if (img) { img.hidden = !onPhoto; credit.hidden = !onPhoto; }
99	    hint.hidden = onPhoto;
100	    outlineBtn.setAttribute("aria-pressed", String(state.outline));
101	    ghost.group.visible = onPhoto ? state.outline : (comp.ghost?.fill ?? 0) + (comp.ghost?.edge ?? 0) > 0;
102	    ghost.fill.opacity = onPhoto ? 0 : comp.ghost?.fill ?? 0.06;
103	    ghost.edge.opacity = onPhoto ? 0.7 : comp.ghost?.edge ?? 0.5;
104	    for (const [id, inst] of instances) inst.layout?.({ active: id === state.comp, onPhoto });
105	    stage.setPhotoView(onPhoto);
106	    if (!onPhoto && resetOrbit) stage.setOrbit(comp.view);
107	  }
108	  toolbar.addEventListener("click", e => {
109	    const b = e.target.closest("button"); if (!b) return;
110	    if (b === outlineBtn) { state.outline = !state.outline; return layout(false); }
111	    const group = b.closest(".seg-group"), key = group.dataset.key;
112	    state[key] = b.dataset.v;
113	    group.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", String(x === b)));
114	    layout();
115	  });
116	
117	  layout();
118	  stage.start(dt => {
119	    carRoot.position.set(0, 0, 0); carRoot.rotation.set(0, 0, 0);
120	    instances.get(state.comp).update(dt, { onPhoto: state.view === "photo" });
121	  });
