  const F0 = (await import("./stops/blitzen-benz/car.js")).default.components[1].params.flow;
  const nose = [[105, 1120], [102, 1165], [75, 1200], [25, 1228], [-50, 1243], [-140, 1250], [-270, 1250]];
  const prof = [...nose, ...F0.profile.filter(([x]) => x <= -800 || F0.profile.indexOf([x]) < 0).filter(([x, z]) => !(x > -800 && z > 1100)), ];
  const F = { ...F0, profile: prof.filter(([x, z]) => !(x >= 71 && z >= 1068 && z < 1120)) };
  console.log(JSON.stringify(F.profile.slice(0, 12)), F.profile.length);
  const g = rasterize(F.profile, F);
  for (const [nu, smag] of [[0.004, 0.16], [0.0015, 0.16]]) {
    const t = createTunnel({ ...g, nu, smag });
    const nx = g.nx, cell = (x, z) => Math.round((F.x0 - x) / F.cell - 0.5) + nx * Math.round(z / F.cell - 0.5);
    let acc = Array(7).fill(0);
    for (let s = 0; s < 4000; s++) { t.step(); if (s >= 2000) [-300, -600, -900, -1200, -1500, -1800, -2100].forEach((x, i) => acc[i] += t.ux[cell(x, 1300)] / t.U / 2000); }
    console.log(nu, "mean u/U 50mm over hood:", acc.map(a => a.toFixed(2)).join(" "));
  }
});'

